using System;using System.Collections.Generic;public class RandomizedCollection{List<int>a=new();Dictionary<int,HashSet<int>>m=new();Random r=new();public RandomizedCollection(){}public bool Insert(int v){if(!m.ContainsKey(v))m[v]=new();bool fresh=m[v].Count==0;m[v].Add(a.Count);a.Add(v);return fresh;}public bool Remove(int v){if(!m.ContainsKey(v)||m[v].Count==0)return false;int i=-1;foreach(int x in m[v]){i=x;break;}m[v].Remove(i);int li=a.Count-1,last=a[li];a[i]=last;if(i!=li){m[last].Remove(li);m[last].Add(i);}a.RemoveAt(li);return true;}public int GetRandom()=>a[r.Next(a.Count)];}
